package com.spamemailnew.backend.service;
import jakarta.annotation.PostConstruct; import org.springframework.core.io.ClassPathResource; import org.springframework.stereotype.Service; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class NaiveBayesClassifier { private final Map<String,Integer> spam=new HashMap<>(), ham=new HashMap<>(); private final Set<String> vocab=new HashSet<>(); private int spamMsgs,hamMsgs,spamWords,hamWords;
@PostConstruct public void train(){ try(BufferedReader r=new BufferedReader(new InputStreamReader(new ClassPathResource("spam.csv").getInputStream(),StandardCharsets.UTF_8))){ String s; boolean first=true; while((s=r.readLine())!=null){if(first){first=false;continue;} String[] a=parse(s); if(a.length<2)continue; String label=a[0].trim().toLowerCase(), text=a[1]; if(!label.equals("spam")&&!label.equals("ham"))continue; List<String>w=tok(text);vocab.addAll(w); if(label.equals("spam")){spamMsgs++;for(String x:w){spam.merge(x,1,Integer::sum);spamWords++;}}else{hamMsgs++;for(String x:w){ham.merge(x,1,Integer::sum);hamWords++;}}} }catch(Exception e){throw new RuntimeException("Could not load spam.csv",e);} System.out.println("Naive Bayes trained: spam="+spamMsgs+", ham="+hamMsgs+", vocab="+vocab.size());}
public Result predict(String text){List<String>w=tok(text);int v=Math.max(vocab.size(),1);double sl=Math.log((double)spamMsgs/(spamMsgs+hamMsgs)),hl=Math.log((double)hamMsgs/(spamMsgs+hamMsgs));for(String x:w){sl+=Math.log((spam.getOrDefault(x,0)+1.0)/(spamWords+v));hl+=Math.log((ham.getOrDefault(x,0)+1.0)/(hamWords+v));}double m=Math.max(sl,hl),sp=Math.exp(sl-m),hp=Math.exp(hl-m),t=sp+hp;sp/=t;hp/=t;return new Result(sp>=hp?"SPAM":"HAM",sp,hp);}
private List<String>tok(String s){return Arrays.stream(s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9\s]"," ").split("\s+")).filter(x->!x.isBlank()).toList();}
private String[]parse(String line){List<String>a=new ArrayList<>();StringBuilder b=new StringBuilder();boolean q=false;for(int i=0;i<line.length();i++){char c=line.charAt(i);if(c=='"'){if(q&&i+1<line.length()&&line.charAt(i+1)=='"'){b.append('"');i++;}else q=!q;}else if(c==','&&!q){a.add(b.toString());b.setLength(0);}else b.append(c);}a.add(b.toString());return a.toArray(new String[0]);}
public record Result(String label,double spamProbability,double hamProbability){} }